SELECT 'STORY' AS kind, st.slug AS ref, st.status, st.type AS subtype, st.age_min||'-'||st.age_max AS ages, (SELECT count(*) FROM story_pages sp WHERE sp.story_id=st.id) AS pages, (SELECT count(*) FROM story_bubbles sb JOIN story_pages sp2 ON sp2.id=sb.page_id WHERE sp2.story_id=st.id) AS bubbles, (SELECT count(*) FROM story_page_localizations l JOIN story_pages sp3 ON sp3.id=l.page_id WHERE sp3.story_id=st.id) AS localizations, (SELECT count(*) FROM asset_links al WHERE al.entity_type='story' AND al.entity_id=st.id) AS links, CASE WHEN st.description_ar IS NULL THEN 'no' ELSE 'yes' END AS has_desc, st.languages FROM stories st ORDER BY st.slug;
SELECT 'BOOK' AS kind, b.id AS ref, b.status, b.type AS subtype, b.age_min||'-'||b.age_max AS ages, b.pages, (SELECT count(*) FROM asset_links al WHERE al.entity_type='book' AND al.entity_id=b.id) AS links, COALESCE(b.series_id,'-') AS series FROM books b ORDER BY b.id;
SELECT 'GAME' AS kind, g.id AS ref, g.status, g.engine_id AS engine, g.age_min||'-'||g.age_max AS ages, g.content_pack, g.help_system, CASE WHEN g.instructions_ar IS NULL THEN 'no' ELSE 'yes' END AS has_instructions, COALESCE(g.episode_id,'-') AS episode, COALESCE(g.learning_objective_id,'-') AS objective, (SELECT count(*) FROM asset_links al WHERE al.entity_type='game' AND al.entity_id=g.id) AS links FROM games g ORDER BY g.id;
SELECT 'PROJECT' AS kind, p.id AS ref, p.status, p.age_min||'-'||p.age_max AS ages, p.materials, p.steps, p.learning_objective_ids AS objectives, (SELECT count(*) FROM asset_links al WHERE al.entity_type='project' AND al.entity_id=p.id) AS links FROM projects p ORDER BY p.id;
SELECT 'CHARACTER' AS kind, c.id AS ref, c.status, s.slug AS series, c.role, COALESCE(c.age,-1) AS age, c.reference_images, c.expressions, c.outfits, CASE WHEN c.voice_actor IS NULL THEN 'no' ELSE 'yes' END AS has_voice, (SELECT count(*) FROM asset_links al WHERE al.entity_type='character' AND al.entity_id=c.id) AS links FROM characters c JOIN series s ON s.id=c.series_id ORDER BY s.slug;
SELECT 'SERIES_WITH_NO_CHARACTERS' AS kind, s.slug AS ref, s.status, s.type AS subtype, (SELECT count(*) FROM episodes e WHERE e.series_id=s.id) AS episodes FROM series s WHERE NOT EXISTS (SELECT 1 FROM characters c WHERE c.series_id=s.id) ORDER BY s.slug;
